mapper.select:
select 

where c.dept_id = #{scope.deptId} and c.library_id = #{scope.libraryId}
and (

        (c.content like concat('%', #{term}, '%') or d.title like concat('%', #{term}, '%'))

)
order by (

        (case when c.content like concat('%', #{term}, '%') then 2 else 0 end
        + case when d.title like concat('%', #{term}, '%') then 1 else 0 end)

) desc, c.chunk_id
limit 48

select 

where c.dept_id = #{scope.deptId} and c.library_id = #{scope.libraryId}
  and c.chunk_id in
  #{id}

select 

where c.dept_id = #{scope.deptId} and c.library_id = #{scope.libraryId}
  and c.content like concat('%', #{code}, '%')
order by c.version_id, c.chunk_index
limit #{limit}

select 

where c.dept_id = #{scope.deptId} and c.library_id = #{scope.libraryId}
  and c.version_id = #{versionId} and c.chunk_index >= #{from} and c.chunk_index <= #{to}
order by c.chunk_index

select i.item_code from md_item i
where i.item_type_code = #{typeCode} and i.enable_flag = 'Y'
  and exists (
    select 1
    from kb_document_chunk c
    join kb_document_version v on v.version_id = c.version_id and v.active = 1 and v.deleted_at is null
    join kb_document d on d.doc_id = c.doc_id and d.deleted_at is null and d.graph_enabled = 1
    where c.version_id = #{versionId} and c.dept_id = #{scope.deptId}
      and c.library_id = #{scope.libraryId}
      and c.content like concat('%', i.item_code, '%')
  )
order by i.item_id limit #{limit}

select 

where c.dept_id = #{version.deptId} and c.library_id = #{version.libraryId}
  and c.version_id = #{version.versionId} and c.chunk_id > #{after}
order by c.chunk_id limit 12
